-- Smart Traveler RAG seed, 1,000 courses. MariaDB 12.3.
-- 어느 DB에서 실행해도 동일하게 재현되도록, place/region을 숫자 ID가 아니라
-- source_provider+source_place_id(TourAPI 콘텐츠ID)와 region_code로 매번 다시 찾는다.
-- (이전 버전은 place_id/region_id를 그대로 박아 넣어서 다른 DB에서는 "Course count or
--  region references do not match" 오류로 막혔다 — 이 파일은 그 문제를 고친 버전이다.)
-- 먼저 region_fixes_and_additions_2026_11.sql / category_seed_2026_11.sql / place_seed_2026_11.sql을
-- 실행해 두어야 한다. 생성한 테스트 계정 100개(rag_seed_test_001..100)에 코스를 10개씩 나눠 배정한다.
-- Do not use the client's --force option. Run through mariadb CLI (DELIMITER support).
-- Visit order is in course.condition_meta.itinerary. Import does not create activity
-- rows because activity.start_time is required. Dates are sample data.
-- Own a full backup before importing. This script adds generation_method (1,'ai')
-- only if code 'ai' is absent and id 1 is free, per the project seed.
USE smart_travel_db;
SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;
SET @rag_seed_previous_sql_mode = @@SESSION.sql_mode;
SET SESSION sql_mode = 'STRICT_ALL_TABLES,NO_BACKSLASH_ESCAPES,NO_ENGINE_SUBSTITUTION';

DROP TEMPORARY TABLE IF EXISTS rag_seed_course, rag_seed_day, rag_seed_visit;
CREATE TEMPORARY TABLE rag_seed_course (
  seed_no INT PRIMARY KEY, region_code VARCHAR(30) NOT NULL,
  destination VARCHAR(100) NOT NULL, start_date DATE NOT NULL, end_date DATE NOT NULL,
  companion_type VARCHAR(30) NOT NULL, adults INT NOT NULL, children INT NOT NULL,
  transport_type VARCHAR(30) NOT NULL, title VARCHAR(200) NOT NULL, summary TEXT NOT NULL,
  preferences JSON NOT NULL, meta_base JSON NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TEMPORARY TABLE rag_seed_day (
  seed_no INT NOT NULL, day_no INT NOT NULL, theme VARCHAR(200) NOT NULL, visit_date DATE NOT NULL,
  PRIMARY KEY(seed_no, day_no)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TEMPORARY TABLE rag_seed_visit (
  seed_no INT NOT NULL, day_no INT NOT NULL, seq INT NOT NULL,
  source_provider VARCHAR(30) NOT NULL, source_place_id VARCHAR(100) NOT NULL,
  PRIMARY KEY(seed_no, day_no, seq)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;




















DELIMITER //
BEGIN NOT ATOMIC
  DECLARE import_lock INT DEFAULT 0;
  DECLARE seed_index INT DEFAULT 1;
  DECLARE method_id INT DEFAULT NULL;
  DECLARE new_course_id BIGINT;
  DECLARE matched_places INT;
  DECLARE matched_regions INT;
  DECLARE base_member_id BIGINT;
  DECLARE inserted_days INT DEFAULT 0;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    IF import_lock = 1 THEN
      DO RELEASE_LOCK('smart_travel_db.rag_seed_course_import');
    END IF;
    RESIGNAL;
  END;

  IF @@session.foreign_key_checks <> 1 OR @@session.check_constraint_checks <> 1 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Enable foreign key and check constraints before import.';
  END IF;
  SELECT GET_LOCK('smart_travel_db.rag_seed_course_import', 10) INTO import_lock;
  IF COALESCE(import_lock, 0) <> 1 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Another seed import holds the lock.';
  END IF;

  START TRANSACTION;
  IF EXISTS (SELECT 1 FROM course WHERE
    JSON_VALUE(condition_meta, '$.seed_batch') = 'smart-traveler-rag-1000-v1') THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'This course seed batch is already present.';
  END IF;
  IF EXISTS (SELECT 1 FROM members WHERE login_id = 'rag_seed_test_001') THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'RAG seed test accounts already exist.';
  END IF;

  IF ROW_COUNT() <> 100 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Expected to insert exactly 100 RAG seed test accounts.';
  END IF;
  SET base_member_id = LAST_INSERT_ID();

  SELECT COUNT(*) INTO matched_regions
  FROM rag_seed_course AS seed
  JOIN region AS r ON BINARY r.region_code = BINARY seed.region_code
       AND BINARY r.full_name = BINARY seed.destination
  LOCK IN SHARE MODE;
  IF matched_regions <> 1000 OR (SELECT COUNT(*) FROM rag_seed_course) <> 1000 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Course count or region references do not match.';
  END IF;
  SELECT COUNT(*) INTO matched_places
  FROM rag_seed_visit AS v
  JOIN place AS p ON p.source_provider = v.source_provider AND p.source_place_id = v.source_place_id
       AND p.is_active = b'1'
  LOCK IN SHARE MODE;
  IF matched_places <> (SELECT COUNT(*) FROM rag_seed_visit) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'A referenced place is missing, inactive, or changed.';
  END IF;

  SELECT MAX(id) INTO method_id FROM generation_method WHERE code = 'ai' LOCK IN SHARE MODE;
  IF method_id IS NULL THEN
    IF EXISTS (SELECT 1 FROM generation_method WHERE id = 1) THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Generation method id 1 is occupied and ai is absent.';
    END IF;
    SET method_id = 1;
  END IF;

  WHILE seed_index <= 1000 DO
      member_no, region_id, region_code, destination, start_date, end_date,
      companion_type, adults, children, transport_type, title, summary,
      preferences_snapshot, condition_meta, generation_method_id, flow_type, status, share_consent
    )
    SELECT base_member_id + ((seed_index - 1) DIV 10), r.region_id, s.region_code, s.destination,
      s.start_date, s.end_date, s.companion_type, s.adults, s.children, s.transport_type,
      s.title, s.summary, s.preferences,
      JSON_SET(s.meta_base, '$.itinerary', (
        SELECT JSON_ARRAYAGG(JSON_OBJECT('day_no', day_level.day_no, 'visits', day_level.visits_json) ORDER BY day_level.day_no)
        FROM (
          SELECT v.seed_no, v.day_no,
                 JSON_ARRAYAGG(JSON_OBJECT('seq', v.seq, 'place_id', p.place_id, 'place_name', p.name,
                                            'place_type', p.place_type, 'address', p.address) ORDER BY v.seq) AS visits_json
          FROM rag_seed_visit v JOIN place p ON p.source_provider = v.source_provider AND p.source_place_id = v.source_place_id
          GROUP BY v.seed_no, v.day_no
        ) day_level
        WHERE day_level.seed_no = s.seed_no
      )),
      method_id, 'COURSE_FIRST', 'done', b'0'
    FROM rag_seed_course s JOIN region r ON BINARY r.region_code = BINARY s.region_code
    WHERE s.seed_no = seed_index;
    IF ROW_COUNT() <> 1 THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Expected exactly one course row for this seed number.';
    END IF;
    SET new_course_id = LAST_INSERT_ID();
    SELECT new_course_id, day_no, theme, visit_date
    FROM rag_seed_day WHERE seed_no = seed_index ORDER BY day_no;
    SET inserted_days = inserted_days + ROW_COUNT();
    SET seed_index = seed_index + 1;
  END WHILE;

  IF inserted_days <> (SELECT SUM(DATEDIFF(end_date, start_date) + 1) FROM rag_seed_course)
     OR inserted_days <> (SELECT COUNT(*) FROM rag_seed_day) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Inserted day count does not match expected duration.';
  END IF;
  COMMIT;
  DO RELEASE_LOCK('smart_travel_db.rag_seed_course_import');
  SELECT 1000 AS courses_inserted, inserted_days AS course_days_inserted, matched_places AS distinct_place_ids,
         base_member_id AS first_test_member_id, base_member_id + 99 AS last_test_member_id;
END//
DELIMITER ;

DROP TEMPORARY TABLE rag_seed_course, rag_seed_day, rag_seed_visit;
SET SESSION sql_mode = @rag_seed_previous_sql_mode;
